contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address caller, address recipient1, address recipient2, uint amount) public payable {
        require(address(this).balance >= amount);
        c.fallback{value: amount}();

        uint cBalanceBefore = address(c).balance;

        bool reverted1;
        try c.withdrawAll(recipient1) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        bool isOwner = (caller == c.owner());

        if (isOwner) {
            assert(!reverted1);
            assert(address(c).balance == 0);
            assert(address(recipient1).balance == cBalanceBefore);
        } else {
            assert(reverted1);
            assert(address(c).balance == cBalanceBefore);
            assert(address(recipient1).balance == 0);
        }
    }
}

