contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);
        c.fallback{value: amount}();

        uint256 cBefore = address(c).balance;
        uint256 rBefore = recipient.balance;

        bool reverted;
        if (caller == address(this)) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            (bool success, ) = address(c).call(
                abi.encodeWithSignature("withdrawAll(address)", recipient)
            );
            reverted = !success;
        }

        assert(
            (caller == address(this) && !reverted && address(c).balance == 0 && recipient.balance == rBefore + cBefore) ||
            (caller != address(this) && reverted && address(c).balance == cBefore && recipient.balance == rBefore)
        );
    }

    receive() external payable {}
}

